	}
	
	$dia = substr($d,0,2);
	$mes = substr($d,2,2);
	
	$mes = intval($mes);
	$hora = substr($d,4,2);
	$minuto = substr($d,6,2);
	$tipo = substr($d,8,1);
	$angle = substr($d,9,4)/10;
	
	$moon = $angle;
	if($z < 1){
	$moon += 180;
    }
	
	$moon -= $ay_value;
	if($moon < 0){$moon += 360.0;}
	
	
	if($moon > 360){$moon -= 360;}
	$sign = floor($moon/30);
	$deg = $moon - $sign*30;
	
	$deg = floor($deg*10)/10;	
	
	$t = $abv[$tipo]." ".$txt." eclipse";
	
	//return "$t... $dia ".$mnames[$mes]." $y at $hora"."h"."$minuto UT (Moon at $deg&deg;".$signos[$sign].")";
	return "$t... $dia ".$mnames[$mes]." $y , $hora"."h"."$minuto UT (Moon $deg&deg;".$signos[$sign].")";
	
}	
function base_from_64 ($n,$b) {
  $t = 0;
  $chars = str_split($n);
  foreach($chars as $c){
    $t = $b * $t + strpos('0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ@#', $c);
  }
  return $t;
}
